var LOGO="data:image/png;base64,";
var J=["Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi","Dimanche"];
var S={staff:[],n:0,cur:null,pl:null,tb:"team",te:"home",sub:"",pf:{},rg:{poste:"",d:[],s:"",e:"",p:"",en:"",nb:""}};
var POSTES={"Caisse":{d:[1,2,3,4,5],s:"11:00",e:"18:30",p:"30"},"Friteuse et cuisine":{d:[0,1,2,3,4],s:"10:30",e:"18:00",p:"30"},"Grill et burgers":{d:[2,3,4,5,6],s:"11:30",e:"19:00",p:"30"},"Préparation et stock":{d:[0,1,2,3,4],s:"07:30",e:"15:00",p:"30"},"Salle et accueil":{d:[0,3,4,5,6],s:"12:00",e:"19:30",p:"30"},"Livraison et plonge":{d:[3,4,5,6,0],s:"17:00",e:"22:00",p:"0"}};
function rg(k,v){var r=S.rg;if(k==="poste"){r.poste=v;var t=POSTES[v];if(t){r.d=t.d.slice();r.s=t.s;r.e=t.e;r.p=t.p}}else if(k==="d"){var ix=r.d.indexOf(v[0]);if(v[1]){if(ix<0)r.d.push(v[0])}else if(ix>=0)r.d.splice(ix,1)}else r[k]=v;draw()}
function regForm(){var r=S.rg;return'<div class="card"><b>Inscrire un équipier</b><label>Date d’entrée dans l’entreprise</label><input type="date" value="'+r.en+'" onchange="rg(\'en\',this.value)"><label>Date de naissance (règles des mineurs)</label><input type="date" value="'+r.nb+'" onchange="rg(\'nb\',this.value)"><label>Poste occupé</label><select onchange="rg(\'poste\',this.value)"><option value="">Choisir un poste</option>'+Object.keys(POSTES).map(function(k){return'<option'+(k===r.poste?" selected":"")+'>'+k+'</option>'}).join("")+'</select><label>Jours de service</label><div style="display:flex;flex-wrap:wrap;gap:6px">'+J.map(function(j,i){var on=r.d.indexOf(i)>=0;return'<label style="margin:0;display:flex;align-items:center;gap:4px;background:'+(on?'var(--rose)':'var(--creme)')+';padding:8px 10px;border-radius:99px"><input type="checkbox" style="width:18px;height:18px;min-height:0" '+(on?"checked ":"")+'onchange="rg(\'d\',['+i+',this.checked])">'+j.slice(0,3)+'</label>'}).join("")+'</div><div class="g3"><div><label>Début</label><input type="time" value="'+r.s+'" onchange="rg(\'s\',this.value)"></div><div><label>Fin</label><input type="time" value="'+r.e+'" onchange="rg(\'e\',this.value)"></div><div><label>Pause (min)</label><input type="number" min="0" step="5" value="'+r.p+'" onchange="rg(\'p\',this.value)"></div></div><small>Horaires proposés selon le poste, modifiables. L’équipier complète ensuite nom, prénom et photo.</small><br><br><button class="btn g" onclick="addE()">Inscrire l’équipier</button></div>'}
var P=function(n){return(n<10?"0":"")+n};
function iso(d){return d.getFullYear()+"-"+P(d.getMonth()+1)+"-"+P(d.getDate())}
function week(){var d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));var a=[];for(var i=0;i<7;i++){a.push(iso(d));d.setDate(d.getDate()+1)}return a}
function tm(s){if(!s)return null;var a=s.split(":");return +a[0]*60+ +a[1]}
function ft(m){return P(Math.floor(m/60)%24)+":"+P(m%60)}
function fh(m){m=Math.round(m);return Math.floor(m/60)+" h "+P(m%60)}
function nowM(){var d=new Date();return d.getHours()*60+d.getMinutes()}
function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function age(e){if(!e.naiss)return 30;var b=new Date(e.naiss),n=new Date(),a=n.getFullYear()-b.getFullYear();if(n<new Date(n.getFullYear(),b.getMonth(),b.getDate()))a--;return a}
function lim(e){var a=age(e);return a<16?{d:420,pb:270,pm:30,r:840,n:20}:a<18?{d:480,pb:270,pm:30,r:720,n:22}:{d:600,pb:360,pm:20,r:660,n:null}}
function dn(e){return(e.prenom||e.nom)?(e.prenom+" "+e.nom).trim():"Équipier n°"+e.n}
function eff(e,d){var r=e.days[d]||{},t=iso(new Date())===d;
 if(r.as){var live=!r.ae&&t,p=(r.pb||0)+(r.pst!=null&&live?nowM()-r.pst:0);return{s:r.as,e:r.ae||(live?ft(nowM()):null),p:p,live:live,act:true}}
 return{s:r.ps,e:r.pe,p:+r.pp||0,live:false}}
function span(x){var a=tm(x.s),b=tm(x.e);if(a==null||b==null)return null;if(b<a)b+=1440;return{a:a,b:b}}
function work(x){var q=span(x);return q?q.b-q.a-x.p:0}
function viol(e){var L=lim(e),W=week(),out=[],tot=0,any=false,prev=null;
 if(!e.nom||!e.prenom||!e.poste)out.push({w:1,t:"Profil incomplet : nom, prénom ou poste manquant."});
 W.forEach(function(d,i){var x=eff(e,d),q=span(x),j=J[i];
  if(x.s&&!x.e&&!x.live){out.push({t:j+" : case vide, heure de fin manquante. Comptabilisation impossible."});prev=null;return}
  if(!x.s&&x.e){out.push({t:j+" : case vide, heure de début manquante."});prev=null;return}
  if(!q){prev=null;return}
  any=true;var w=work(x),g=q.b-q.a;tot+=w;
  if(w>L.d)out.push({t:j+" : "+fh(w)+" de travail, maximum "+fh(L.d)+" par jour."});
  if(g>L.pb&&x.p<L.pm)out.push({t:j+" : pause de "+L.pm+" min obligatoire (pause actuelle : "+x.p+" min)."});
  if(L.n&&(q.b>L.n*60||q.a<360))out.push({t:j+" : travail de nuit interdit (entre "+L.n+" h et 6 h) pour ce salarié."});
  if(prev!=null&&q.a+1440-prev<L.r)out.push({t:j+" : repos de "+fh(q.a+1440-prev)+" seulement avant ce service, minimum "+(L.r/60)+" h consécutives."});
  prev=q.b>1440?q.b-1440+1440:q.b});
 if(tot>2100)out.push({t:"Semaine : "+fh(tot)+" de travail, maximum 35 h."});
 if(any){var off=W.map(function(d){return!span(eff(e,d))});
  if(age(e)<18){if(!(off[6]&&(off[5]||off[0])))out.push({t:"Repos hebdomadaire : 2 jours consécutifs minimum, dimanche inclus, pour un mineur."})}
  else if(off.indexOf(true)<0)out.push({t:"Repos hebdomadaire : 24 h consécutives minimum par semaine."})}
 return out}
function tot(e){var s=0,p=0;week().forEach(function(d){var x=eff(e,d);if(span(x)){s+=work(x);p+=x.p}});return{s:s,p:p}}
var IC={home:'<path d="M3 11l9-8 9 8M5 10v10h14V10"/>',cal:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M3 10h18M8 3v4M16 3v4"/>',bell:'<path d="M6 17V11a6 6 0 0112 0v6l2 2H4zM10 21h4"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/>',team:'<circle cx="9" cy="8" r="3.5"/><circle cx="17" cy="9" r="2.5"/><path d="M2 20c0-4 3-6 7-6s7 2 7 6M16 14c3 0 6 1 6 5"/>',go:'<path d="M5 12h14M13 6l6 6-6 6"/>'};
function ic(n){return'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+IC[n]+'</svg>'}
function nav(el,items,cur,fn,bad){document.getElementById(el).innerHTML=items.map(function(i){return'<button class="'+(cur===i[0]?"on":"")+'" onclick="'+fn+'(\''+i[0]+'\')">'+ic(i[2])+i[1]+(i[0]==="alerts"&&bad?'<span class="bd">'+bad+'</span>':"")+'</button>'}).join("")}
function setB(t){S.tb=t;draw()}function setE(t){S.te=t;S.sub="";draw()}
function vw(v){document.getElementById("cb").classList.toggle("show",v==="b");document.getElementById("ce").classList.toggle("show",v==="e");document.getElementById("sb").className="btn"+(v==="b"?"":" o");document.getElementById("se").className="btn"+(v==="e"?"":" o")}
function addE(){var r=S.rg,en=r.en,nb=r.nb;
 if(S.staff.length>=6){alert("L’équipe est limitée à 6 équipiers.");return}
 if(!en||!nb||!r.poste||!r.s||!r.e||!r.d.length){alert("Renseignez la date d’entrée, la date de naissance, le poste, les jours de service et les horaires.");return}
 S.n++;var e={id:S.n,n:S.n,nom:"",prenom:"",poste:r.poste,photo:"",entree:en,naiss:nb,days:{}};week().forEach(function(d,i){if(r.d.indexOf(i)>=0)e.days[d]={ps:r.s,pe:r.e,pp:r.p}});S.staff.push(e);S.rg={poste:"",d:[],s:"",e:"",p:"",en:"",nb:""};S.cur=S.cur||e.id;S.pl=S.pl||e.id;draw()}
function delE(id){S.staff=S.staff.filter(function(e){return e.id!==id});if(S.cur===id)S.cur=S.staff[0]?S.staff[0].id:null;if(S.pl===id)S.pl=S.cur;draw()}
function G(id){return S.staff.filter(function(e){return e.id===id})[0]}
function plan(d,k,v){var e=G(S.pl);e.days[d]=e.days[d]||{};e.days[d][k]=v;draw()}
function setF(k,v){var e=G(S.cur);e[k]=v;draw()}
function photo(inp){var f=inp.files[0];if(!f)return;var r=new FileReader();r.onload=function(){setF("photo",r.result)};r.readAsDataURL(f)}
function act(a){var e=G(S.cur),d=iso(new Date()),r=e.days[d]=e.days[d]||{},t=ft(nowM());
 if(a==="start"){r.as=t;r.pb=0}
 if(a==="pause"){r.pst=nowM()}
 if(a==="resume"){r.pb=(r.pb||0)+nowM()-r.pst;r.pst=null}
 if(a==="end"){if(r.pst!=null){r.pb=(r.pb||0)+nowM()-r.pst;r.pst=null}r.ae=t}
 draw()}
function sl(a,txt,cls){return'<div class="slide '+(cls||"")+'" data-a="'+a+'"><span class="l">'+txt+'</span><div class="th">'+ic("go")+'</div></div>'}
function alerts(list,who){return list.length?list.map(function(v){return'<div class="al'+(v.w?" w":"")+'">'+(who?'<b>'+esc(who)+' – </b>':"")+esc(v.t)+'</div>'}).join(""):'<div class="al okc">Aucune alerte : tous les horaires respectent les règles.</div>'}
function legal(){return'<h2>Mentions légales</h2><div class="card"><b>Nom de l’application</b><br>La Bonne Frite fast food – Planning des équipiers<h3>Éditeurs</h3>Juliette V et Louise S, classe de 1re STMG, lycée.<h3>Hébergeur</h3>GitHub Pages.<h3>Sources des données</h3>Code du travail (Légifrance) et Service-Public.fr, consultés en novembre 2026.<h3>Avertissement</h3>Simulation pédagogique : les résultats sont indicatifs et ne remplacent pas l’avis d’un professionnel.<h3>Données personnelles</h3>Aucune donnée personnelle n’est collectée ni enregistrée, aucun cookie n’est utilisé.<h3>Crédits</h3>Logo « La Bonne Frite » : créé pour le projet des éditeurs. Police Nunito : Vernon Adams, licence SIL OFL, via Google Fonts. Icônes : dessinées en SVG par les éditeurs.</div><button class="btn o" onclick="S.sub=\'\';draw()">Retour</button>'}
function drawB(){var h="",all=[];S.staff.forEach(function(e){viol(e).forEach(function(v){all.push([dn(e),v])})});
 if(S.tb==="team"){h='<h2>Mon équipe ('+S.staff.length+'/6)</h2>'+regForm()+'';
  h+=S.staff.map(function(e){var t=tot(e);return'<div class="card"><div class="row"><b>'+esc(dn(e))+'</b><span class="pill">'+age(e)+' ans</span></div><small>'+esc(e.poste||"Poste à renseigner")+' · entré le '+esc(e.entree)+'</small><div class="row"><span>Semaine : '+fh(t.s)+' · Pauses : '+fh(t.p)+'</span><button class="btn o" style="width:auto;min-height:40px;padding:6px 14px" onclick="delE('+e.id+')">Retirer</button></div></div>'}).join("");
  h+='<button class="btn o" onclick="S.tb=\'legal\';draw()">Mentions légales</button>'}
 else if(S.tb==="plan"){h='<h2>Planning de la semaine</h2>';
  if(!S.staff.length)h+='<div class="card">Inscrivez d’abord un équipier.</div>';else{
  h+='<select onchange="S.pl=+this.value;draw()">'+S.staff.map(function(e){return'<option value="'+e.id+'"'+(e.id===S.pl?" selected":"")+'>'+esc(dn(e))+'</option>'}).join("")+'</select>';
  var e=G(S.pl);h+=week().map(function(d,i){var r=e.days[d]||{};return'<div class="card"><b>'+J[i]+'</b> <small>'+d.slice(8)+'/'+d.slice(5,7)+(span(eff(e,d))?'':' · repos')+'</small><div class="g3"><div><label>Début</label><input type="time" value="'+(r.ps||"")+'" onchange="plan(\''+d+'\',\'ps\',this.value)"></div><div><label>Fin</label><input type="time" value="'+(r.pe||"")+'" onchange="plan(\''+d+'\',\'pe\',this.value)"></div><div><label>Pause (min)</label><input type="number" min="0" step="5" value="'+(r.pp||"")+'" onchange="plan(\''+d+'\',\'pp\',this.value)"></div></div></div>'}).join("")}}
 else if(S.tb==="alerts"){h='<h2>Alertes</h2>'+(all.length?all.map(function(a){return alerts([a[1]],a[0])}).join(""):alerts([]))}
 else h=legal();
 document.getElementById("sb_").innerHTML=h;
 nav("nb",[["team","Équipe","team"],["plan","Planning","cal"],["alerts","Alertes","bell"]],S.tb==="legal"?"team":S.tb,"setB",all.length)}
function drawE(){var h="",e=G(S.cur),W=week(),td=iso(new Date());
 var sel=S.staff.length?'<select onchange="S.cur=+this.value;S.sub=\'\';draw()" aria-label="Équipier">'+S.staff.map(function(x){return'<option value="'+x.id+'"'+(x.id===S.cur?" selected":"")+'>'+esc(dn(x))+'</option>'}).join("")+'</select>':"";
 if(!e){document.getElementById("se_").innerHTML='<img class="logo" src="'+LOGO+'" alt="Logo La Bonne Frite"><div class="card c">Aucun équipier pour le moment. Le patron doit d’abord vous inscrire.</div>';document.getElementById("ne").innerHTML="";return}
 var v=viol(e),x=eff(e,td),r=e.days[td]||{};
 if(S.te==="home"){h=sel+'<img class="logo" src="'+LOGO+'" alt="Logo La Bonne Frite"><h2 class="c">Bonjour '+esc(e.prenom||"")+' !</h2>';
  h+='<div class="card c"><small>Horaire de la journée</small><div class="big">'+(r.ps&&r.pe?r.ps+' – '+r.pe:'Repos')+'</div>'+(r.pp?'<small>Pause prévue : '+r.pp+' min</small>':"")+'</div>';
  if(v.length)h+='<div class="al">'+v.length+' alerte(s) : voir l’onglet Alertes.</div>';
  if(!r.as)h+=sl("start","Début de service","g");
  else if(!r.ae){h+='<div class="card c">En service depuis '+r.as+'<br><b>Travaillé : '+fh(work(x))+'</b></div>';
   h+=(r.pst!=null)?sl("resume","Fin de pause","m"):sl("pause","Début de pause","m");h+=sl("end","Fin de service")}
  else h+='<div class="card c"><div class="big">À demain !</div>Service de '+r.as+' à '+r.ae+' · Travaillé : '+fh(work(x))+'</div>'}
 else if(S.te==="plan"){h='<h2>Planning de la semaine</h2>'+W.map(function(d,i){var y=eff(e,d);return'<div class="card" style="'+(d===td?"border:2px solid var(--or)":"")+'"><div class="row"><b>'+J[i]+'</b>'+(span(y)?'<span class="pill">'+y.s+' – '+(y.e||"…")+'</span>':'<span class="pill">Repos</span>')+'</div>'+(span(y)?'<small>Pause : '+y.p+' min</small>':"")+'</div>'}).join("")}
 else if(S.te==="alerts"){var m=W.indexOf(td),pr=e.days[td]||{};h='<h2>Alertes</h2><h3>Horaire impossible</h3>'+alerts(v)+'<h3>Notifications</h3>';
  h+='<div class="al w">'+(pr.ps?'Reprise de service à '+(pr.pp&&pr.ps?ft(tm(pr.ps)):pr.ps)+' h':'Aucun service prévu aujourd’hui')+'</div>'+(pr.pe?'<div class="al w">Fin de service à '+pr.pe+' h</div>':"");
  h+='<h3>Les deux prochains jours</h3>'+[1,2].map(function(k){var d=W[m+k];if(!d)return'<div class="card">Voir le planning de la semaine prochaine.</div>';var y=eff(e,d);return'<div class="card"><b>'+J[m+k]+'</b> : '+(span(y)?y.s+' – '+(y.e||"…"):'Repos')+'</div>'}).join("")}
 else if(S.sub==="legal")h=legal();
 else{var t=tot(e);h=sel+'<h2 class="c">Mon profil</h2><div class="ph">'+(e.photo?'<img src="'+e.photo+'" alt="Photo de profil">':esc((e.prenom||"?").charAt(0).toUpperCase()))+'</div><div class="c"><b>'+esc(dn(e))+'</b><br><small>'+esc(e.poste||"Poste à renseigner")+' · entré le '+esc(e.entree)+'</small></div><div class="g2" style="margin:12px 0"><div class="card c"><small>Heures de service</small><div class="big">'+fh(t.s)+'</div></div><div class="card c"><small>Heures de pause</small><div class="big">'+fh(t.p)+'</div></div></div>';
  h+='<div class="card"><b>Mes informations</b><label>Nom</label><input value="'+esc(e.nom)+'" onchange="setF(\'nom\',this.value)"><label>Prénom</label><input value="'+esc(e.prenom)+'" onchange="setF(\'prenom\',this.value)"><label>Poste occupé (défini par le patron)</label><input value="'+esc(e.poste)+'" disabled><label>Date d’entrée (remplie par le patron)</label><input value="'+esc(e.entree)+'" disabled><label>Photo de profil (facultative)</label><input type="file" accept="image/*" onchange="photo(this)"></div><button class="btn o" onclick="S.sub=\'legal\';draw()">Mentions légales</button>'}
 document.getElementById("se_").innerHTML=h;
 nav("ne",[["home","Accueil","home"],["plan","Planning","cal"],["alerts","Alertes","bell"],["profil","Profil","user"]],S.sub?"profil":S.te,"setE",v.length)}
function draw(){var a=document.getElementById("sb_"),b=document.getElementById("se_"),x=a.scrollTop,y=b.scrollTop;drawB();drawE();a.scrollTop=x;b.scrollTop=y}
var drag=null;
document.addEventListener("pointerdown",function(ev){var t=ev.target.closest(".th");if(!t)return;drag={t:t,s:t.parentNode,x:ev.clientX};t.setPointerCapture(ev.pointerId)});
document.addEventListener("pointermove",function(ev){if(!drag)return;var m=drag.s.clientWidth-drag.t.clientWidth-10,d=Math.max(0,Math.min(m,ev.clientX-drag.x));drag.t.style.transform="translateX("+d+"px)";drag.d=d/m});
document.addEventListener("pointerup",function(){if(!drag)return;var d=drag;drag=null;if(d.d>.85)act(d.s.dataset.a);else d.t.style.transform=""});
setInterval(function(){if(!drag&&!/INPUT|SELECT/.test(document.activeElement.tagName))draw()},30000);
draw();
